
import { useEffect, useState } from "react";
import "./App.css";

import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import Projects from "./components/Projects";
import Skills from "./components/Skills";
import Contact from "./components/Contact";
import Footer from "./components/Footer";

// Content is baked into the build (generated by `manage.py export_portfolio`).
// No API request on page load, so the site renders instantly even when the
// Django backend is asleep.
import portfolio from "./data/portfolio.json";

function App() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    message: "",
  });

  // Dark mode state
  const [theme, setTheme] = useState(() => {
    return localStorage.getItem("portfolio-theme") || "light";
  });

  // Apply selected theme
  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    localStorage.setItem("portfolio-theme", theme);
  }, [theme]);

  // Toggle between light and dark mode
  const toggleTheme = () => {
    setTheme((current) =>
      current === "light" ? "dark" : "light"
    );
  };

  return (
    <main>
      <Navbar theme={theme} toggleTheme={toggleTheme} />

      <Hero myprofile={portfolio.profile} />

      <Projects projects={portfolio.projects} />

      <Skills myskills={portfolio.skills} />

      <Contact
        formData={formData}
        setFormData={setFormData}
      />

      <Footer myprofile={portfolio.profile} />
    </main>
  );
}

export default App;
